{
 "findings": [
  {
   "title": "The same JNDI lookup for the order datasource is repeated in nine classes",
   "severity": "medium",
   "files": [
    "src/com/harbor/oms/catalog/CatalogAdminBean.java",
    "src/com/harbor/oms/customer/CustomerBean.java",
    "src/com/harbor/oms/fulfillment/FulfillmentServiceBean.java",
    "src/com/harbor/oms/inventory/InventoryServiceBean.java",
    "src/com/harbor/oms/order/OrderServiceBean.java",
    "src/com/harbor/oms/order/SalesOrderBean.java",
    "src/com/harbor/oms/pricing/PricingServiceBean.java",
    "src/com/harbor/oms/product/ProductBean.java",
    "src/com/harbor/oms/shipment/ShipmentBean.java"
   ],
   "evidence_quote": "return (DataSource) naming.lookup(\"java:comp/env/jdbc/OrderDS\");",
   "why_it_matters": "Each class builds its own InitialContext and hard-codes the datasource name. The lookup cannot be replaced by container injection in one place, and a rename or a move off JNDI touches nine files."
  },
  {
   "title": "PricingService manages its own transaction although the descriptor declares container-managed transactions",
   "severity": "high",
   "files": [
    "dd/ejb-jar.xml",
    "src/com/harbor/oms/pricing/PricingServiceBean.java"
   ],
   "evidence_quote": "UserTransaction transaction = sessionContext.getUserTransaction();",
   "why_it_matters": "ejb-jar.xml says the bean is container-managed and lists applyPriceOverride as Required, yet the bean begins and commits its own transaction. Two owners of one boundary will not survive a move to a runtime that honours only one."
  },
  {
   "title": "SQL is built by string concatenation in OrderDao",
   "severity": "high",
   "files": [
    "src/com/harbor/oms/dao/OrderDao.java"
   ],
   "evidence_quote": "\"FROM sales_order WHERE customer_id = '\" + customerId + \"' \"",
   "why_it_matters": "findByCustomerAndStatus pastes the customer id and the status into the statement text, so a crafted value rewrites the query. Every other statement in the class is parameterised, which makes this one both easy to fix and easy to miss."
  },
  {
   "title": "CatalogAdminBean is both an HTTP servlet and an EJB that writes to the database",
   "severity": "high",
   "files": [
    "src/com/harbor/oms/catalog/CatalogAdminBean.java",
    "web/WEB-INF/web.xml"
   ],
   "evidence_quote": "public class CatalogAdminBean extends HttpServlet implements SessionBean {",
   "why_it_matters": "web.xml maps the class as a servlet and the EJB container also owns it as a session bean, and it opens its own connection to update product prices. The web tier and the data tier cannot be split while one class is both."
  }
 ],
 "modules": [
  {
   "name": "order",
   "responsibility": "Order entry and the sales order entity: placing, pricing and persisting an order."
  },
  {
   "name": "customer",
   "responsibility": "The buyer entity, credit limit and hold status."
  },
  {
   "name": "product",
   "responsibility": "The product entity and its price."
  },
  {
   "name": "pricing",
   "responsibility": "Region quotes and buyer-approved price overrides."
  },
  {
   "name": "inventory",
   "responsibility": "Stock levels per warehouse."
  },
  {
   "name": "fulfillment",
   "responsibility": "Allocation of an order to shipments."
  },
  {
   "name": "shipment",
   "responsibility": "The shipment entity and its status."
  },
  {
   "name": "catalog",
   "responsibility": "Browser-driven price maintenance for the warehouse office."
  },
  {
   "name": "dao",
   "responsibility": "Raw JDBC data access for customers, orders, products and shipments."
  },
  {
   "name": "web",
   "responsibility": "Two servlets and a JSP front end for the order desk."
  }
 ],
 "risks": [
  "Two classes of problem sit in the data path: SQL text built from request values, and a transaction with two owners.",
  "Every class reaches its collaborators through JNDI, so none can be tested or moved without an application server.",
  "The descriptors are WebLogic-specific; any move off that server needs the vendor settings re-read, not just the standard ones."
 ],
 "recommended_order": [
  "Parameterise the SQL in OrderDao first: it is small, it is a vulnerability, and nothing depends on it.",
  "Settle the transaction boundary in PricingService before touching anything that calls it.",
  "Split CatalogAdminBean into a servlet and a service so the web and EJB tiers can move separately.",
  "Replace the repeated JNDI lookups with one injected datasource once the boundaries above are settled."
 ],
 "coverage": {
  "files_total": 51,
  "files_read": 48,
  "unread_reason": "The two SQL scripts and one WebLogic web descriptor were not opened: no build file, descriptor or class names them."
 }
}
